/bin/bash -lc "node --input-type=module <<'EOF'
const urls = ['/products/lamp?currency=USD', '/products/lamp?currency=EUR', '/products/vase?currency=USD', '/products/vase?currency=EUR', '/products/missing?currency=EUR']
for (const path of urls) {
  const start = performance.now()
  const response = await fetch("'`http://localhost:3100${path}`)
  const reader = response.body.getReader()
  const chunks = []
  for (;;) {
    const { value, done } = await reader.read()
    if (done) break
    const body = new TextDecoder().decode(value)
    chunks.push({ ms: Math.round(performance.now() - start), length: value.length, shell: body.includes('"'Loading product details...'), relatedFallback: body.includes('Loading related products...'), product: body.includes('<h1>'), related: body.includes('Stone vase') || body.includes('Brass lamp') })
  }
  const html = (await (await fetch("'`http://localhost:3100${path}`)).text())
  const title = html.match(/<h1>(.*?)<'"\\/h1>/)?.[1] ?? null
  const price = html.match(/<p>((?:USD|EUR) [0-9.]+)<\\/p>/)?.[1] ?? null
  console.log(JSON.stringify({ path, status: response.status, title, price, chunks }))
}
EOF"

/bin/bash -lc "node --input-type=module <<'EOF'
for (const path of ['/products/lamp?currency=EUR', '/products/lamp?currency=EUR', '/products/lamp']) {
  const start = performance.now()
  const response = await fetch("'`http://localhost:3100${path}`)
  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  let text = '"''
  let detailsAt = null
  let relatedAt = null
  for (;;) {
    const { value, done } = await reader.read()
    if (done) break
    text += decoder.decode(value)
    if (detailsAt === null && text.includes('<h1>Brass lamp</h1>')) detailsAt = Math.round(performance.now() - start)
    if (relatedAt === null && text.includes('<p>Stone vase</p>')) relatedAt = Math.round(performance.now() - start)
  }
  console.log(JSON.stringify({ path, status: response.status, detailsAt, relatedAt, price: text.match(/<p>((?:USD|EUR) [0-9.]+)<\\/p>/)?.[1] }))
}
EOF"

/bin/bash -lc "node --input-type=module <<'EOF'
for (const [path, expected] of [
  ['/products/lamp?currency=EUR', ['Brass lamp', 'EUR 110.40']],
  ['/products/vase?currency=USD', ['Stone vase', 'USD 80.00']],
  ['/products/vase?currency=EUR', ['Stone vase', 'EUR 73.60']],
  ['/products/lamp?currency=GBP', ['Brass lamp', 'USD 120.00']],
  ['/products/lamp?currency=EUR&currency=USD', ['Brass lamp', 'USD 120.00']],
]) {
  const response = await fetch("'`http://localhost:3100${path}`)
  const html = await response.text()
  const actual = [html.match(/<h1>(.*?)<'"\\/h1>/)?.[1], html.match(/<p>((?:USD|EUR) [0-9.]+)<\\/p>/)?.[1]]
  if (response.status "'!== 200 || actual.some((value, index) => value !== expected[index])) throw new Error(`${path}: ${JSON.stringify(actual)}`)
  console.log(`${path}: ${actual.join('"', ')}"'`)
}
EOF'
